Let me write out the hook:

```ts
import { useQueryClient } from "@tanstack/react-query";
import { useEffect } from "react";
import { authClient } from "@/lib/auth-client";

export function useActiveLeague() {
  const queryClient = useQueryClient();
  const { data: session } = authClient.useSession();
  const { data: organizations = [] } = authClient.useListOrganizations();

  const activeOrgId = session?.session?.activeOrganizationId;
  const activeLeague = activeOrgId
    ? organizations.find((org) => org.id === activeOrgId) ?? organizations[0]
    : organizations[0];

  useEffect(() => {
    if (organizations.length === 0) return;
    if (activeOrgId && organizations.some((org) => org.id === activeOrgId)) return;
    void authClient.organization
      .setActive({ organizationId: organizations[0].id })
      .then(({ error }) => {
        if (error) console.error("Failed to set active league", error);
        void queryClient.invalidateQueries();
      });
  }, [activeOrgId, organizations, queryClient]);

  const switchLeague = async (organizationId: string) => {
    const { error } = await authClient.organization.setActive({ organizationId });
    if (error) {
      console.error("Failed to set active league", error);
      return false;
    }
    await queryClient.invalidateQueries();
    return true;
  };

  return { activeLeague, organizations, isLoading: ... , switchLeague };
}
```

