			seasonId: ctx.season.id,
		});
	}),

	getWeeklyStats: seasonProcedure.query(async ({ ctx }) => {
		return seasonPlayerRepository.getWeeklyStats({
			db: ctx.db,
			seasonId: ctx.season.id,
		});
	}),
} satisfies TRPCRouterRecord;

