```tsx
import { router } from "expo-router";
import { useQuery } from "@tanstack/react-query";
import * as WebBrowser from "expo-web-browser";
import { useEffect } from "react";
import { FlatList, StyleSheet, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { StandingRow, type StandingItem } from "@/components/standing-row";
import { ThemedText } from "@/components/themed-text";
import { ThemedView } from "@/components/themed-view";
import { Button } from "@/components/ui/button";
import { BottomTabInset, MaxContentWidth, Spacing } from "@/constants/theme";
import { useActiveLeague } from "@/hooks/use-active-league";
import { useTRPC } from "@/lib/trpc";

export default function HomeScreen() {
	const trpc = useTRPC();
	const { activeLeague, organizations, isLoading } = useActiveLeague();

	// All hooks before any early return (rules of hooks).
	const activeSeasonQuery = useQuery(
		trpc.season.findActive.queryOptions(undefined, { enabled: Boolean(activeLeague) })
	);
	const activeSeason = activeSeasonQuery.data;
	const standingsQuery = useQuery(
		trpc.seasonPlayer.getStanding.queryOptions(
			{ seasonSlug: activeSeason?.slug ?? "" },
			{ enabled: Boolean(activeSeason) }
		)
	);

	useEffect(() => {
		if (!isLoading && activeLeague && activeSeasonQuery.data === null) {
			router.replace("/seasons");
		}
	}, [isLoading, activeLeague, activeSeasonQuery.data]);

	if (isLoading) {
		return (
			<ThemedView style={styles.center}>
				<ThemedText>Loading…</ThemedText>
			</ThemedView>
		);
	}

	if (organizations.length === 0) {
		return (
			<ThemedView style={styles.center}>
				<ThemedText type="title" style={styles.centerText}>
					No league yet
				</ThemedText>
				<ThemedText type="small" themeColor="textSecondary" style={styles.centerText}>
					Create a league on scorebrawl.com to get started.
				</ThemedText>
				<View style={styles.centerButton}>
					<Button
						variant="outline"
						onPress={() => WebBrowser.openBrowserAsync("https://scorebrawl.com")}
					>
						Create a league
					</Button>
				</View>
			</ThemedView>
		);
	}

	if (!activeLeague) {
		return (
			<ThemedView style={styles.center}>
				<ThemedText>No active league</ThemedText>
			</ThemedView>
		);
	}

	return (
		<ThemedView style={styles.container}>
			<SafeAreaView edges={["bottom"]} style={styles.safeArea}>
				{activeSeason && (
					<View style={styles.header}>
						<ThemedText type="small" themeColor="textSecondary">
							{activeLeague.name}
						</ThemedText>
						<ThemedText type="title">{activeSeason.name}</ThemedText>
					</View>
				)}
				<FlatList
					data={standingsQuery.data ?? []}
					keyExtractor={(item) => item.id}
					renderItem={({ item, index }) => (
						<StandingRow item={item as StandingItem} rank={index + 1} />
					)}
					contentContainerStyle={styles.list}
				/>
			</SafeAreaView>
		</ThemedView>
	);
}
```

IMPORTANT — the `styles` object:
- `container`: the row-flex centered pattern from the current index.tsx (`flex: 1, flexDirection: "row", justifyContent: "center"`)
- `safeArea`: `flex: 1, maxWidth: MaxContentWidth, paddingHorizontal: Spacing.four, paddingBottom: BottomTabInset + Spacing.three`
- `center`: `flex: 1, alignItems: "center", justifyContent: "center", gap: Spacing.three, paddingHorizontal: Spacing.four`
- `centerText`: `textAlign: "center"`
- `centerButton`: `marginTop: Spacing.four, width: "100%", maxWidth: 320`
- `header`: `gap: Spacing.one, marginTop: Spacing.four, marginBottom: Spacing.three`
- `list`: `paddingBottom: Spacing.four`

Keep the current index.tsx's `container`/`safeArea` styles. Note the Home screen is now inside the drawer, so the top safe area is handled by the drawer header — use `edges={["bottom"]}` only.

The `item as StandingItem` cast: the real `getStanding` item has MORE fields than `StandingItem` (structural subtyping means it's assignable directly — the cast is a fallback if TS complains about `image` being `string | null` vs `StandingItem.image?: string | null`; drop the cast if not needed). Prefer no cast if it typechecks; the plan mentions a cast may be needed because `image` is typed differently — verify and use whatever compiles cleanly without `@ts-expect-error`.

Check the exact `queryOptions` signature for the INPUTLESS `findActive`: in @trpc/tanstack-react-query v11, inputless procedures' `queryOptions` takes `(opts?)` directly (the input is void). So it may be `trpc.season.findActive.queryOptions({ enabled: Boolean(activeLeague) })` (single options arg). Verify against the type and use whichever compiles. Do NOT use `@ts-expect-error`/`@ts-ignore`.

### Step 5: Create `apps/mobile/src/app/(drawer)/(tabs)/seasons.tsx`

```tsx
import { useQuery } from "@tanstack/react-query";
import { FlatList, StyleSheet, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";

import { ThemedText } from "@/components/themed-text";
import { ThemedView } from "@/components/themed-view";
import { BottomTabInset, MaxContentWidth, Spacing } from "@/constants/theme";
import { formatDate, getSeasonStatus } from "@/lib/collections/season";
import { useTRPC } from "@/lib/trpc";

export default function SeasonsScreen() {
	const trpc = useTRPC();
	const { data: seasons = [], isLoading } = useQuery(trpc.season.getAll.queryOptions());

	return (
		<ThemedView style={styles.container}>
			<SafeAreaView edges={["bottom"]} style={styles.safeArea}>
				<ThemedText type="title" style={styles.title}>
					Seasons
				</ThemedText>
				<FlatList
					data={seasons}
					keyExtractor={(item) => item.id}
					renderItem={({ item }) => {
						const status = getSeasonStatus(item);
						return (
							<View style={styles.row}>
								<View style={styles.rowInfo}>
									<ThemedText style={styles.rowName}>{item.name}</ThemedText>
									<ThemedText type="small" themeColor="textSecondary">
										{formatDate(item.startDate)}
										{item.endDate ? ` → ${formatDate(item.endDate)}` : ""}
									</ThemedText>
								</View>
								<ThemedText type="smallBold">{status}</ThemedText>
							</View>
						);
					}}
					contentContainerStyle={styles.list}
					ListEmptyComponent={
						isLoading ? (
							<ThemedText type="small" themeColor="textSecondary" style={styles.empty}>
								Loading…
							</ThemedText>
						) : (
							<ThemedText type="small" themeColor="textSecondary" style={styles.empty}>
								No seasons yet
							</ThemedText>
						)
					}
				/>
			</SafeAreaView>
		</ThemedView>
	);
}

const styles = StyleSheet.create({
	container: {
		flex: 1,
		flexDirection: "row",
		justifyContent: "center",
	},
	safeArea: {
		flex: 1,
		maxWidth: MaxContentWidth,
		paddingHorizontal: Spacing.four,
		paddingBottom: BottomTabInset + Spacing.three,
	},
	title: {
		marginTop: Spacing.four,
		marginBottom: Spacing.three,
	},
	list: {
		paddingBottom: Spacing.four,
	},
	row: {
		flexDirection: "row",
		alignItems: "center",
		justifyContent: "space-between",
		paddingVertical: Spacing.three,
		borderBottomWidth: StyleSheet.hairlineWidth,
		borderBottomColor: "rgba(128,128,128,0.25)",
	},
	rowInfo: {
		flex: 1,
	},
	rowName: {
		fontWeight: "600",
	},
	empty: {
		textAlign: "center",
		marginTop: Spacing.five,
	},
});
```

Note: `seasons` may be typed `Season[] | undefined` — the `= []` default narrows it. `formatDate` takes a `Date`; `item.startDate` is a Date (check the type — if it's a string, adjust `formatDate` or pass `new Date(...)`).

### Step 6: Add Seasons trigger to `apps/mobile/src/components/app-tabs.web.tsx`

Read the file. It uses `expo-router/ui` TabTrigger/TabList/TabSlot (web tabs). Add a `TabTrigger` for `name="seasons"` with `href="/seasons"` next to the Home trigger, with label "Seasons". Match the existing structure/style. Remove any leftover Explore references if present.

### Step 7: Typecheck + lint

